sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

	var instanceURL = gs.getProperty('glide.servlet.uri');
	var portalSuffix = 'ec';

	var grPortal = new GlideRecord('sp_portal');
	grPortal.addQuery('inactive', false);
	grPortal.addQuery('default', true);
	grPortal.orderByDesc('sys_updated_on');
	grPortal.setLimit(1);
	grPortal.query();

	if (grPortal.next()) {
		portalSuffix = grPortal.getValue('url_suffix');
	}

	var deviceHealthPageURL = instanceURL + portalSuffix + '?id=dh_digital_experience';
	var deviceHealthPageText = gs.getMessage('Open My Device Health');

	template.print('<a href="' + deviceHealthPageURL + '">' + deviceHealthPageText + '</a>');

})(current, template, email, email_action, event);
